local buckets = {}
for id, entry in species do
	entry.id = id
	buckets[entry.tier] = buckets[entry.tier] or {}
	buckets[entry.tier][entry.rarity] = buckets[entry.tier][entry.rarity] or {}
	table.insert(buckets[entry.tier][entry.rarity], id)
end
-- Stable order so a given roll maps to the same species on every server.
for _, byRarity in buckets do
	for _, ids in byRarity do
		table.sort(ids)
	end
end

return { species = species, buckets = buckets }
